using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class LabLightInspect {
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var lights=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>(true)).Where(l=>Vector3.Distance(l.transform.position,room.position)<17||l.type==LightType.Directional).ToArray();var renderers=root.GetComponentsInChildren<Renderer>().Where(r=>Vector3.Distance(r.bounds.center,room.position)<15).Where(r=>r.sharedMaterials.Any(m=>m&&(m.name.Contains("Lamp")||m.name.Contains("Light")||m.IsKeywordEnabled("_EMISSION")))).ToArray();var result=new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,selected=Selection.activeGameObject?PathOf(Selection.activeGameObject.transform):null,ambientMode=RenderSettings.ambientMode.ToString(),ambientIntensity=RenderSettings.ambientIntensity,lights=lights.Select(l=>new{path=PathOf(l.transform),l.name,l.enabled,active=l.gameObject.activeInHierarchy,type=l.type.ToString(),position=l.transform.position.ToString("F5"),localPosition=l.transform.localPosition.ToString("F5"),rotation=l.transform.eulerAngles.ToString("F5"),forward=l.transform.forward.ToString("F5"),l.intensity,l.range,l.spotAngle,l.innerSpotAngle,shadows=l.shadows.ToString(),l.shadowBias,l.shadowNormalBias,l.cullingMask,bakeType=l.lightmapBakeType.ToString(),color=l.color.ToString("F5")}).ToArray(),emissiveRenderers=renderers.Select(r=>new{path=PathOf(r.transform),bounds=r.bounds.ToString("F4"),position=r.transform.position.ToString("F5"),rotation=r.transform.eulerAngles.ToString("F5"),mesh=r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):"",mats=r.sharedMaterials.Select(m=>new{m.name,path=AssetDatabase.GetAssetPath(m),shader=m.shader.name,emissionKeyword=m.IsKeywordEnabled("_EMISSION"),emission=m.HasProperty("_EmissionColor")?m.GetColor("_EmissionColor").ToString("F5"):"",emissionMap=m.HasProperty("_EmissionMap")?AssetDatabase.GetAssetPath(m.GetTexture("_EmissionMap")):""}).ToArray()}).ToArray()};string o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Lighting/"));Directory.CreateDirectory(o);File.WriteAllText(o+"before.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,selected=result.selected,lights=lights.Length,emissiveRenderers=renderers.Length,output=o};}
}
